import { util } from '@aws-appsync/utils';

// Reads the VP row's current SharedWith string before it gets replaced, so
// the next pipeline step can diff old vs. new grantees and keep the
// VirtualParticipantShareIndex mirror table in sync.
export function request(ctx) {
  return {
    operation: 'GetItem',
    key: util.dynamodb.toMapValues({ id: ctx.args.input.id }),
  };
}

export function response(ctx) {
  const item = ctx.result;
  ctx.stash.oldSharedWith = item && typeof item.SharedWith === 'string' ? item.SharedWith : '';
  return {};
}
